/**
 * Demo jobs for one week, modelled on a jobs export: drivers, booked and actual times,
 * durations, delays, statuses, charges, payment methods and evidence states follow the
 * export. Customer names, phone numbers and street addresses are fictional (only the
 * postcode district is kept) and every job reference is a synthetic "TMV-D..." value
 * derived by a one-way hash, so no record here can be looked up in production and no
 * customer's personal data is in this repo or the public demo.
 * Day offsets are relative to 16 October: 0 is "today" in the demo.
 * The export's mistyped £898,988,888.00 job (13 Oct, MAN VAN) was removed at the
 * owner's request, as it is being removed from production.
 * Generated by a one-off script; edit the data, not the shape.
 */
export interface ExportJob {
  id: string; driver: string; customer: string; phone: string; pickup: string; dropoff: string;
  start: [number, number, number]; actualStart: [number, number, number] | null; actualFinish: [number, number, number] | null;
  minutes: number | null; actualMinutes: number | null; delay: number | null; band: string; status: string;
  base: number | null; extra: number | null; overtime: number | null; total: number | null; charged: number | null;
  method: string; payment: string; billing: string; evidence: Record<string, string>;
}

